<?php
namespace App\Jobs;
use App\Models\Examination;use App\Models\ChoiceValidationRun;use App\Services\ChoiceValidation\ChoiceValidationProcessingService;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Throwable;
final class ProcessChoiceValidation implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=1;public int $timeout=0;public function __construct(public readonly int $examinationId,public readonly int $runId){$this->onQueue((string)config('choice-validation.queue','imports'));}public function handle(ExaminationConnectionManager $connections,ChoiceValidationProcessingService $service):void{$exam=Examination::query()->findOrFail($this->examinationId);$connections->configure($exam);try{$service->run($this->runId);}catch(Throwable $e){ChoiceValidationRun::query()->whereKey($this->runId)->update(['status'=>'failed','failure_message'=>$e->getMessage(),'finished_at'=>now()]);throw $e;}finally{$connections->disconnect();}}}
